class DataAccessException(Exception):
    def __init__(self, message, cause=None):
        super().__init__(message)
        self.__cause__ = cause


class PaymentException(Exception):
    def __init__(self, message, cause=None):
        super().__init__(message)
        self.__cause__ = cause


class InsufficientFundsException(Exception):
    pass


class Account:
    def __init__(self, account_id: int, balance: float):
        self.account_id = account_id
        self.balance = balance

    def debit(self, amount: float):
        if amount > self.balance:
            raise InsufficientFundsException(f"Balance too low for account {self.account_id}")
        self.balance -= amount

    def credit(self, amount: float):
        self.balance += amount


class Database:
    def __init__(self):
        self._accounts = {1: Account(1, 500.0), 2: Account(2, 100.0)}

    def query(self, account_id: int) -> Account:
        account = self._accounts.get(account_id)
        if account is None:
            raise RuntimeError(f"SQL error: no row for id={account_id}")
        return account


# Layer 1 - repository (data access)
class AccountRepository:
    def __init__(self):
        self.db = Database()

    def find_by_id(self, account_id: int) -> Account:
        try:
            return self.db.query(account_id)
        except RuntimeError as e:
            # translate: SQL detail stays here, not exposed upward
            raise DataAccessException("Account lookup failed", e) from e


# Layer 2 - service (domain)
class PaymentService:
    def __init__(self):
        self.repo = AccountRepository()

    def transfer(self, from_id: int, to_id: int, amount: float):
        try:
            from_account = self.repo.find_by_id(from_id)
            to_account = self.repo.find_by_id(to_id)
            from_account.debit(amount)
            to_account.credit(amount)
        except DataAccessException as e:
            raise PaymentException("Transfer failed: accounts unavailable", e) from e
        except InsufficientFundsException as e:
            raise PaymentException("Transfer failed: insufficient funds", e) from e


