import java.util.HashMap;
import java.util.Map;

class DataAccessException extends RuntimeException {
    DataAccessException(String msg, Throwable cause) { super(msg, cause); }
}

class PaymentException extends RuntimeException {
    PaymentException(String msg, Throwable cause) { super(msg, cause); }
    PaymentException(String msg) { super(msg); }
}

class InsufficientFundsException extends RuntimeException {
    InsufficientFundsException(String msg) { super(msg); }
}

class Account {
    long id;
    double balance;

    Account(long id, double balance) {
        this.id = id;
        this.balance = balance;
    }

    void debit(double amount) {
        if (amount > balance) {
            throw new InsufficientFundsException("Balance too low for account " + id);
        }
        balance -= amount;
    }

    void credit(double amount) {
        balance += amount;
    }
}

class Database {
    private final Map<Long, Account> accounts = new HashMap<>();

    Database() {
        accounts.put(1L, new Account(1, 500.0));
        accounts.put(2L, new Account(2, 100.0));
    }

    Account query(long id) {
        Account account = accounts.get(id);
        if (account == null) {
            throw new RuntimeException("SQL error: no row for id=" + id);
        }
        return account;
    }
}

// Layer 1 - repository (data access)

class AccountRepository {
    private final Database db = new Database();

    Account findById(long id) {
        try {
            return db.query(id);
        } catch (RuntimeException e) {
            // translate: SQL detail stays here, not exposed upward
            throw new DataAccessException("Account lookup failed", e);
        }
    }
}

// Layer 2 - service (domain)

class PaymentService {
    private final AccountRepository repo = new AccountRepository();

    void transfer(long fromId, long toId, double amount) {
        try {
            Account from = repo.findById(fromId);
            Account to = repo.findById(toId);
            from.debit(amount);
            to.credit(amount);
        } catch (DataAccessException e) {
            throw new PaymentException("Transfer failed: accounts unavailable", e);
        } catch (InsufficientFundsException e) {
            throw new PaymentException("Transfer failed: insufficient funds", e);
        }
    }
}

class Response {
    int status;
    String message;

    private Response(int status, String message) {
        this.status = status;
        this.message = message;
    }

    static Response ok(String message) { return new Response(200, message); }
    static Response error(int status, String message) { return new Response(status, message); }

    @Override
    public String toString() {
        return "Response{status=" + status + ", message=" + message + "}";
    }
}

// Layer 3 - controller (boundary)

class PaymentController {
    private final PaymentService service = new PaymentService();

    Response transfer(long from, long to, double amount) {
        try {
            service.transfer(from, to, amount);
            return Response.ok("Transfer complete");
        } catch (PaymentException e) {
            System.out.println("[log] Transfer failed: " + e.getMessage());
            return Response.error(400, e.getMessage());
        }
    }
}

public class Main {
    public static void main(String[] args) {
        PaymentController controller = new PaymentController();
        System.out.println(controller.transfer(1, 2, 50.0));
        System.out.println(controller.transfer(2, 1, 1000.0));
    }
}

