#include <iostream>
#include <string>
#include <unordered_map>
#include <stdexcept>

class DataAccessException : public std::runtime_error {
public:
    explicit DataAccessException(const std::string& msg) : std::runtime_error(msg) {}
};

class PaymentException : public std::runtime_error {
public:
    explicit PaymentException(const std::string& msg) : std::runtime_error(msg) {}
};

class InsufficientFundsException : public std::runtime_error {
public:
    explicit InsufficientFundsException(const std::string& msg) : std::runtime_error(msg) {}
};

class Account {
public:
    long id;
    double balance;

    Account(long id = 0, double balance = 0.0) : id(id), balance(balance) {}

    void debit(double amount) {
        if (amount > balance) {
            throw InsufficientFundsException("Balance too low for account " + std::to_string(id));
        }
        balance -= amount;
    }

    void credit(double amount) {
        balance += amount;
    }
};

class Database {
    std::unordered_map<long, Account> accounts;
public:
    Database() {
        accounts[1] = Account(1, 500.0);
        accounts[2] = Account(2, 100.0);
    }

    Account& query(long id) {
        auto it = accounts.find(id);
        if (it == accounts.end()) {
            throw std::runtime_error("SQL error: no row for id=" + std::to_string(id));
        }
        return it->second;
    }
};

// Layer 1 - repository (data access)
class AccountRepository {
    Database db;
public:
    Account& findById(long id) {
        try {
            return db.query(id);
        } catch (const std::exception& e) {
            // translate: SQL detail stays here, not exposed upward
            throw DataAccessException(std::string("Account lookup failed: ") + e.what());
        }
    }
};

// Layer 2 - service (domain)
class PaymentService {
    AccountRepository repo;
public:
    void transfer(long fromId, long toId, double amount) {
        try {
            Account& from = repo.findById(fromId);
            Account& to = repo.findById(toId);
            from.debit(amount);
            to.credit(amount);
        } catch (const DataAccessException& e) {
            throw PaymentException("Transfer failed: accounts unavailable");
        } catch (const InsufficientFundsException& e) {
            throw PaymentException("Transfer failed: insufficient funds");
        }
    }
};

struct Response {
    int status;
    std::string message;

    static Response ok(const std::string& message) { return Response{200, message}; }
    static Response error(int status, const std::string& message) { return Response{status, message}; }
};

std::ostream& operator<<(std::ostream& os, const Response& r) {
    os << "Response{status=" << r.status << ", message=" << r.message << "}";
    return os;
}

// Layer 3 - controller (boundary)
class PaymentController {
    PaymentService service;
public:
    Response transfer(long from, long to, double amount) {
        try {
            service.transfer(from, to, amount);
            return Response::ok("Transfer complete");
        } catch (const PaymentException& e) {
            std::cout << "[log] Transfer failed: " << e.what() << std::endl;
            return Response::error(400, e.what());
        }
    }
};

int main() {
    PaymentController controller;
    std::cout << controller.transfer(1, 2, 50.0) << std::endl;
    std::cout << controller.transfer(2, 1, 1000.0) << std::endl;
    return 0;
}

