class PaymentException(Exception):
    pass


class ErrorResponse:
    def __init__(self, code: str, message: str):
        self.code = code
        self.message = message

    def __repr__(self):
        return f"ErrorResponse(code={self.code}, message={self.message})"


class ResponseEntity:
    def __init__(self, status: int, body: ErrorResponse):
        self.status = status
        self.body = body

    @staticmethod
    def bad_request(body: ErrorResponse):
        return ResponseEntity(400, body)

    @staticmethod
    def internal_server_error(body: ErrorResponse):
        return ResponseEntity(500, body)

    def __repr__(self):
        return f"ResponseEntity(status={self.status}, body={self.body})"


# simulates a framework-level global exception handler (e.g. @ControllerAdvice)
class GlobalExceptionHandler:
    def handle_payment(self, e: PaymentException):
        print(f"[log] Payment error: {e}")
        return ResponseEntity.bad_request(ErrorResponse("PAYMENT_FAILED", str(e)))

    def handle_all(self, e: Exception):
        print(f"[log] Unexpected error: {e}")
        # never leak internal details to the client
        return ResponseEntity.internal_server_error(ErrorResponse("INTERNAL_ERROR", "An unexpected error occurred"))

    # the framework routes to the most specific handler automatically
    def dispatch(self, e: Exception):
        if isinstance(e, PaymentException):
            return self.handle_payment(e)
        return self.handle_all(e)


if __name__ == "__main__":
    handler = GlobalExceptionHandler()

    try:
        raise PaymentException("card declined")
    except Exception as e:
        print(handler.dispatch(e))

    try:
        raise RuntimeError("null pointer somewhere")
    except Exception as e:
        print(handler.dispatch(e))

