#include <iostream>
#include <string>
#include <stdexcept>

class PaymentException : public std::runtime_error {
public:
    explicit PaymentException(const std::string& msg) : std::runtime_error(msg) {}
};

class ErrorResponse {
public:
    std::string code;
    std::string message;
    ErrorResponse(const std::string& code, const std::string& message) : code(code), message(message) {}
};

std::ostream& operator<<(std::ostream& os, const ErrorResponse& r) {
    os << "ErrorResponse{code=" << r.code << ", message=" << r.message << "}";
    return os;
}

class ResponseEntity {
public:
    int status;
    ErrorResponse body;
    ResponseEntity(int status, ErrorResponse body) : status(status), body(body) {}

    static ResponseEntity badRequest(ErrorResponse body) { return ResponseEntity(400, body); }
    static ResponseEntity internalServerError(ErrorResponse body) { return ResponseEntity(500, body); }
};

std::ostream& operator<<(std::ostream& os, const ResponseEntity& r) {
    os << "ResponseEntity{status=" << r.status << ", body=" << r.body << "}";
    return os;
}

// simulates a framework-level global exception handler (e.g. @ControllerAdvice)
class GlobalExceptionHandler {
public:
    ResponseEntity handlePayment(const PaymentException& e) {
        std::cout << "[log] Payment error: " << e.what() << std::endl;
        return ResponseEntity::badRequest(ErrorResponse("PAYMENT_FAILED", e.what()));
    }

    ResponseEntity handleAll(const std::exception& e) {
        std::cout << "[log] Unexpected error: " << e.what() << std::endl;
        // never leak internal details to the client
        return ResponseEntity::internalServerError(ErrorResponse("INTERNAL_ERROR", "An unexpected error occurred"));
    }

    // the framework routes to the most specific handler automatically
    ResponseEntity dispatch(const std::exception& e) {
        if (const auto* pe = dynamic_cast<const PaymentException*>(&e)) {
            return handlePayment(*pe);
        }
        return handleAll(e);
    }
};

int main() {
    GlobalExceptionHandler handler;

    try {
        throw PaymentException("card declined");
    } catch (const std::exception& e) {
        std::cout << handler.dispatch(e) << std::endl;
    }

    try {
        throw std::runtime_error("null pointer somewhere");
    } catch (const std::exception& e) {
        std::cout << handler.dispatch(e) << std::endl;
    }

    return 0;
}

