class DataAccessException(Exception):
    pass


class PaymentException(Exception):
    def __init__(self, message, cause=None):
        super().__init__(message)
        self.__cause__ = cause


class Account:
    def __init__(self, account_id: int, balance: float):
        self.account_id = account_id
        self.balance = balance

    def debit(self, amount: float):
        if amount > self.balance:
            raise DataAccessException(f"Insufficient balance for account {self.account_id}")
        self.balance -= amount


class AccountRepository:
    def find_by_id(self, account_id: int) -> Account:
        return Account(account_id, 100.0)


# Inner layer - translate only, NO logging here
class PaymentService:
    def __init__(self):
        self.repo = AccountRepository()

    def transfer(self, from_id: int, to_id: int, amount: float):
        try:
            self.repo.find_by_id(from_id).debit(amount)
        except DataAccessException as e:
            raise PaymentException("Transfer failed", e) from e  # no log here


class Request:
    def __init__(self, from_id: int, to_id: int, amount: float):
        self.from_id = from_id
        self.to_id = to_id
        self.amount = amount


class Response:
    def __init__(self, status: int, message: str):
        self.status = status
        self.message = message

    @staticmethod
    def ok():
        return Response(200, "OK")

    @staticmethod
    def error(status: int, message: str):
        return Response(status, message)

    def __repr__(self):
        return f"Response(status={self.status}, message={self.message})"


# Boundary layer - log ONCE here with full context
class PaymentController:
    def __init__(self):
        self.service = PaymentService()

    def transfer(self, req: Request):
        try:
            self.service.transfer(req.from_id, req.to_id, req.amount)
            return Response.ok()
        except PaymentException as e:
            print(f"[log] Transfer failed from={req.from_id} to={req.to_id} "
                  f"amount={req.amount:.2f} cause={e}")  # context + cause
            return Response.error(400, str(e))


if __name__ == "__main__":
    controller = PaymentController()
    print(controller.transfer(Request(1, 2, 500.0)))

