    long id;
    double balance;
    Account(long id, double balance) : id(id), balance(balance) {}
    void debit(double amount) {
        if (amount > balance) {
            throw DataAccessException("Insufficient balance for account " + std::to_string(id));
        }
        balance -= amount;
    }
};

class AccountRepository {
public:
    Account findById(long id) {
        return Account(id, 100.0);
    }
};

