class PaymentService {
    AccountRepository repo;
public:
    void transfer(long from, long to, double amount) {
        try {
            Account account = repo.findById(from);
            account.debit(amount);
        } catch (const DataAccessException& e) {
            throw PaymentException("Transfer failed"); // no log here
        }
    }
};

struct Request {
    long from, to;
    double amount;
    Request(long from, long to, double amount) : from(from), to(to), amount(amount) {}
};

