class PaymentController {
    PaymentService service;
public:
    Response transfer(const Request& req) {
        try {
            service.transfer(req.from, req.to, req.amount);
            return Response::ok();
        } catch (const PaymentException& e) {
            char buf[128];
            snprintf(buf, sizeof(buf), "[log] Transfer failed from=%ld to=%ld amount=%.2f cause=%s",
                     req.from, req.to, req.amount, e.what()); // context + cause
            std::cout << buf << std::endl;
            return Response::error(400, e.what());
        }
    }
};

